import{_ as e,o as t,c as a,ag as l}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-10-08（古生物学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/paleontology/science-daily-2026-10-08.md","filePath":"topics/paleontology/science-daily-2026-10-08.md"}'),c={name:"topics/paleontology/science-daily-2026-10-08.md"};function r(n,o,i,s,d,p){return t(),a("div",null,[...o[0]||(o[0]=[l('<h1 id="科学日报-·-2026-10-08-古生物学" tabindex="-1">科学日报 · 2026-10-08（古生物学） <a class="header-anchor" href="#科学日报-·-2026-10-08-古生物学" aria-label="Permalink to &quot;科学日报 · 2026-10-08（古生物学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> — 第31期</p></blockquote><hr><h2 id="侏罗纪会游泳的哺乳形动物与哺乳动物咽部转型-nature" tabindex="-1">侏罗纪会游泳的哺乳形动物与哺乳动物咽部转型（Nature） <a class="header-anchor" href="#侏罗纪会游泳的哺乳形动物与哺乳动物咽部转型-nature" aria-label="Permalink to &quot;侏罗纪会游泳的哺乳形动物与哺乳动物咽部转型（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ DOI: 10.1038/s41586-026-11107-0</p></blockquote><ul><li>标本：中国中侏罗世出土的一具保存精美的<strong>哺乳形动物化石</strong>（mammaliaform，现代哺乳动物的演化前身）。</li><li>关键解剖：罕见保存了类似兽亚纲的<strong>咽腔顶（throat passage）与舌骨</strong>——提示兽亚纲式<strong>吞咽、饮水、吮乳</strong>所需的关键软组织解剖，在齿兽类（Docodonta）与哺乳动物的<strong>共同祖先</strong>中就已演化出来，远早于现代哺乳动物兴起。</li><li>形态：化石具备大量<strong>游泳适应</strong>特征，填补了早期哺乳动物骨盆与后肢解剖的关键空白；高度特化的犬齿与<strong>伪裂齿</strong>指示食虫/食肉习性。</li><li>洞察：与第27期（2026-09-16）侏罗纪声景呼应——<strong>中生代哺乳形动物已高度生态分化</strong>（会游泳、会超声通讯），不是&quot;等待崛起的配角&quot;。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/paleontology/index.md</code> ｜ 第31期 科学板块</p></blockquote><p>关键词：哺乳形动物、中侏罗世、咽腔顶、舌骨、吞咽/吮乳起源、游泳适应、伪裂齿、中生代生态分化 关联：<code>topics/paleontology/science-daily-2026-09-16.md</code>（侏罗纪声景：中生代生态分化的同一论点）、<code>topics/paleoanthropology/</code>（脊椎动物演化谱系）</p>',9)])])}const _=e(c,[["render",r]]);export{g as __pageData,_ as default};
